def order(depends_on):
    placed, result = set(), []
    remaining = dict(depends_on)
    while remaining:
        ready = sorted(t for t, parents in remaining.items() if set(parents) <= placed)
        if not ready:
            raise ValueError("circular")
        for t in ready:
            result.append(t)
            placed.add(t)
            del remaining[t]
    return result

print(order({"sale": ["store"], "store": ["region"], "region": []}))

